import itertools
from pysat.solvers import Minisat22

edges = [(i, j) for i in range(12) for j in range(i+1, 12)]
edge_to_var = {(i,j): k+1 for k, (i,j) in enumerate(edges)}

clauses = []
for quad in itertools.combinations(range(12), 4):
    quad_edges = list(itertools.combinations(quad, 2))
    vars_list = [edge_to_var[tuple(sorted(e))] for e in quad_edges]
    clauses.append(vars_list[:])  # at least one blue (1)
    clauses.append([-v for v in vars_list])  # at least one red (0)

fixed = {7:0, 9:0, 23:1, 27:0, 28:0, 29:0, 33:1, 34:0, 39:1, 40:0, 53:0, 58:0, 63:0}
for idx, val in fixed.items():
    v = idx + 1
    if val == 0:
        clauses.append([-v])
    else:
        clauses.append([v])

with Minisat22() as solver:
    solver.append_formula(clauses)
    if solver.solve():
        sol = solver.get_model()
        coloring = [1 if sol[i] > 0 else 0 for i in range(66)]
        print(coloring)
    else:
        print("UNSATISFIABLE")
